from itertools import combinations
S={(0,0),(0,1),(1,1),(1,2),(2,0),(2,1)}
Q={(0,0),(0,2),(1,0),(1,1),(1,2),(2,1)}
def dists(P):
    return sorted((a[0]-b[0])**2+(a[1]-b[1])**2 for a,b in combinations(P,2))
print(dists(S));print(dists(Q));print(dists(S)==dists(Q))

def transforms(P):
    opts=[]
    for flip in [False,True]:
        for rot in range(4):
            def f(pt):
                r,c=pt
                if flip: c=-c
                for _ in range(rot): r,c=c,-r
                return r,c
            X=[f(p) for p in P]
            minr=min(r for r,c in X); minc=min(c for r,c in X)
            norm={(r-minr,c-minc) for r,c in X}
            opts.append((flip,rot,norm))
    return opts
for flip,rot,norm in transforms(S):
    if norm==Q: print('match',flip,rot)
print(transforms(S))

